)

func TestAmazonDependencies(t *testing.T) {
	tests := []struct {
		release string
		want    []string
	}{
		{"2018.03", []string{"yum-utils"}},
		{"2 (Karoo)", []string{"yum-utils"}},
		{"2022 (Amazon Linux)", []string{"yum-utils"}},
		{"2023 (Amazon Linux 2023)", []string{}},
		{"2025 (Amazon Linux)", []string{}},
	}
